export function createQueue() {
  const entries = []
  const done = new Set()
  const sequence = new WeakMap()
  let nextSequence = 0

  function append(message) {
    sequence.set(message, nextSequence++)
    entries.push(message)
  }

  return {
    enqueue(message) {
      append({ ...message, attempts: message.attempts ?? 0 })
    },
    dequeue(now) {
      for (let i = 0; i < entries.length; i++) {
        const entry = entries[i]
        if (done.has(entry.id)) continue

        // With no clock argument, retain the queue's original FIFO API. The
        // pump supplies `now` so a delayed head can yield to unrelated keys.
        if (now !== undefined) {
          if (entry.retryAt !== undefined && now < entry.retryAt) continue
          const entrySequence = sequence.get(entry)
          const hasEarlierForKey = entries.some((other) =>
            other !== entry &&
            !done.has(other.id) &&
            other.key === entry.key &&
            sequence.get(other) < entrySequence
          )
          if (hasEarlierForKey) continue
        }

        return entries.splice(i, 1)[0]
      }
      return null
    },

