run(steps = Infinity) {
  for (let i = 0; i < steps; i++) {
    const now = clock.now()
    const message = queue.dequeue(now)
    if (message === null) break
    if (dedup.isDuplicate(message.id, now)) {
      queue.ack(message.id)
      continue
    }

    sink.emit(message)
    // Emitting is the delivery boundary. Commit the id before running code
    // that can report an uncertain result, so retry never emits it again.
    dedup.record(message.id, clock.now())

    let ok = false
    try {
      ok = processMessage(message)
    } catch {
      // A thrown error is a failed attempt and follows the same retry path.
    }

    if (!ok) {
      message.attempts += 1
      if (message.attempts >= maxAttempts) {
        queue.ack(message.id)
        sink.failed(message)
        continue
      }
      message.retryAt = retryWithBackoff(clock).scheduleRetry(message.attempts, clock.now())
      queue.requeue(message)
      continue
    }
    queue.ack(message.id)
  }
},

