args.command:
@'
import assert from 'node:assert/strict'
import { createQueue, createDedup, createPump, createSink } from './src/index.js'

function fixture(messages, processMessage, maxAttempts = 3) {
  let now = 0
  const queue = createQueue()
  const sink = createSink()
  for (const message of messages) queue.enqueue(message)
  const pump = createPump({ queue, dedup: createDedup({ windowMs: 50 }), sink, clock: { now: () => now }, processMessage, maxAttempts })
  return { queue, sink, pump, advance(value) { now = value } }
}

{
  let calls = 0
  const f = fixture([{ id: 'a', key: 'K', payload: 1 }], () => ++calls > 1)
  f.pump.run(10)
  assert.deepEqual(f.sink.deliveredIds(), ['a'])
  assert.equal(calls, 1)
  f.advance(1000)
  f.pump.run(10)
  assert.deepEqual(f.sink.deliveredIds(), ['a'])
  assert.equal(calls, 2)
}

{
  const attempts = new Map()
  const f = fixture([
    { id: 'a', key: 'K', payload: 1 },
    { id: 'b', key: 'K', payload: 2 },
    { id: 'x', key: 'X', payload: 3 },
  ], (message) => {
    const count = (attempts.get(message.id) ?? 0) + 1
    attempts.set(message.id, count)
    return message.id !== 'a' || count > 1
  })
  f.pump.run(10)
  assert.deepEqual(f.sink.deliveredIds(), ['a', 'x'])
  f.advance(100)
  f.pump.run(10)
  assert.deepEqual(f.sink.deliveredIds(), ['a', 'x', 'b'])
  assert.equal(attempts.get('a'), 2)
}

{
  let calls = 0
  const f = fixture([{ id: 'e', key: 'K', payload: 1 }], () => { calls += 1; throw new Error('uncertain') }, 2)
  f.pump.run(10)
  f.advance(100)
  f.pump.run(10)
  assert.deepEqual(f.sink.deliveredIds(), ['e'])
  assert.deepEqual(f.sink.failedIds(), ['e'])
  assert.equal(calls, 2)
}

console.log('adversarial delivery checks passed')
